proxy.caddy:
# Caddy reference config for jackett, generated by the hub from its image.yml.
# Caddy and the jackett container share a docker network; replace example.com with your domain.
# Caddy fetches the certificate and passes websockets through on its own.

jackett.example.com {
	# API paths stay open so client applications keep working.
	@api path /api /api/* /dl /dl/*
	handle @api {
		reverse_proxy jackett:9117
